// Generated by qa-tester © 2026 Nikita Morozov (ניקיטה מורוזוב / Никита Морозов). All rights reserved. ID: QAT-NM-2026-344086DC45B0
// #6e5ece (6a993d666cd36172db6e5ece) «פיתוח: תאימות פלטפורמה, רספונסיביות ונגישות» — экраны кандидата ДО звонка, без расхода OpenAI.
// Кейсы CALL-014 (прокрутка, цели 44, RTL, обрезка), CALL-015 (клавиатура до листа согласия), CALL-016 (контраст),
// CALL-017 (неподдерживаемый браузер). Звонковый CALL-018 — a11y-call-end-keyboard.spec.ts (@call).
// НЕ prod-safe: каждый тест создаёт своего кандидата «QA-AUTO-A11Y-…» (business, link_only — без письма/SMS); кандидаты не
// удаляются (правило проекта). Попытка звонка не начинается нигде (страховка blockCallStarts).
// Устройства: CALL-014 и CALL-017 — без пометки (тикет про адаптивность): десктоп меряет 360/390/1440, iPhone/Android — своё окно.
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import { blockCallStarts, scrollWidth } from './support';
import {
  A11Y, SCREENS, newCandidateLink, tapBtn, expectLayoutOk, focused, tabTo, expectContrastOk, NO_MEDIA_DEVICES,
} from './a11y-support';

const HASH = '#6a993d666cd36172db6e5ece';

test.describe(`Экраны кандидата — адаптивность и доступность (${HASH})`, () => {
  test(`ברוכים הבאים → איך זה עובד → פרטי הלקוח → לפני שמתחילים и «צריכים עזרה?»: нет горизонтальной прокрутки, цели ≥44×44, html dir=rtl lang=he, текст не обрезан (десктоп: 360/390/1440) @data ${HASH}`, async ({ browser, page, baseURL }, testInfo) => {
    test.setTimeout(4 * 60_000);
    const name = `QA-AUTO-A11Y-L-${runStamp()}`;
    const link = await newCandidateLink(browser, name, baseURL!);
    testInfo.annotations.push({ type: 'test-data', description: `кандидат «${name}» (согласие не отмечено), не удаляется` });
    const widths = testInfo.project.name === 'tests' ? [360, 390, 1440] : null; // телефоны — только своё окно
    const blocked = await blockCallStarts(page);

    await page.goto(link);
    await expect(page.getByRole('button', { name: A11Y.welcomeCta })).toBeVisible({ timeout: 30_000 });
    // Источник: AC2 «אין גלילה אופקית במובייל», AC2/דרישה 8 «שטח מגע 44 על 44», AC4 «RTL… ללא חיתוך», דרישה 7 «360–1920».
    for (const [i, s] of SCREENS.entries()) {
      await expect(page.getByRole('button', { name: s.ready })).toBeVisible({ timeout: 30_000 });
      await expectLayoutOk(page, s.id, widths);
      if (i === 0) {
        // Лист помощи «?» поверх вступления.
        await tapBtn(page, A11Y.help);
        await expect(page.getByText(A11Y.helpTitle, { exact: true }).filter({ visible: true }).first()).toBeVisible();
        await expectLayoutOk(page, 'help-sheet', widths);
        await tapBtn(page, A11Y.helpClose);
        await expect(page.getByText(A11Y.helpTitle, { exact: true }).filter({ visible: true })).toHaveCount(0);
      }
      await tapBtn(page, s.ready);
    }
    await expect(page.getByText(A11Y.consentTitle).first()).toBeVisible();
    await expect(page.getByRole('checkbox').first()).toBeVisible();
    await expectLayoutOk(page, 'consent-sheet', widths);
    expect(blocked.start + blocked.voice, 'старт попытки без нажатия').toBe(0);
  });

  test(`клавиатура: весь путь до листа согласия Tab+Enter, видимая обводка на каждой остановке; «?» → фокус на «סגירה וחזרה למסך», Esc → фокус снова на «?»; лист согласия — фокус внутри, флажок пробелом @desktop @data ${HASH}`, async ({ browser, page, baseURL }, testInfo) => {
    test.setTimeout(3 * 60_000);
    const name = `QA-AUTO-A11Y-K-${runStamp()}`;
    const link = await newCandidateLink(browser, name, baseURL!);
    testInfo.annotations.push({ type: 'test-data', description: `кандидат «${name}» (флажок согласия отмечен, «להתחיל» не нажат), не удаляется` });
    await blockCallStarts(page);

    await page.goto(link);
    await expect(page.getByRole('button', { name: A11Y.welcomeCta })).toBeVisible({ timeout: 30_000 });

    // Источник: AC5 «סדר המעבר הגיוני ומיקוד המקלדת נראה לעין»; факт 14.10: «?» раньше основной кнопки.
    const stops = await tabTo(page, new RegExp(A11Y.welcomeCta));
    const helpIdx = stops.findIndex((s) => A11Y.help.test(s));
    expect(helpIdx, `«?» не встретился до «${A11Y.welcomeCta}»: ${stops.join(' → ')}`).toBeGreaterThanOrEqual(0);
    const backIdx = stops.findIndex((s) => s === A11Y.back);
    if (backIdx >= 0) expect(backIdx, '«חזרה» должна идти раньше «?»').toBeLessThan(helpIdx);

    // Лист помощи: открыть с клавиатуры, фокус внутри на «סגירה וחזרה למסך», Esc закрывает и возвращает фокус на «?».
    await page.keyboard.press('Shift+Tab');
    for (let i = 0; i < 10 && !A11Y.help.test((await focused(page)).name); i++) await page.keyboard.press('Shift+Tab');
    expect((await focused(page)).name).toMatch(A11Y.help);
    await page.keyboard.press('Enter');
    await expect(page.getByText(A11Y.helpTitle, { exact: true }).filter({ visible: true }).first()).toBeVisible();
    await expect.poll(async () => (await focused(page)).name).toBe(A11Y.helpClose);
    expect((await focused(page)).visibleRing, 'обводка на «סגירה וחזרה למסך»').toBe(true);
    await page.keyboard.press('Escape');
    await expect(page.getByText(A11Y.helpTitle, { exact: true }).filter({ visible: true })).toHaveCount(0);
    await expect.poll(async () => (await focused(page)).name).toMatch(A11Y.help);

    // Вперёд по экранам только клавиатурой.
    await tabTo(page, new RegExp(A11Y.welcomeCta));
    await page.keyboard.press('Enter');
    await expect(page.getByRole('button', { name: A11Y.howCta })).toBeVisible();
    await tabTo(page, new RegExp(A11Y.howCta));
    await page.keyboard.press('Enter');
    await expect(page.getByRole('button', { name: A11Y.clientCta })).toBeVisible();
    await tabTo(page, new RegExp(`^${A11Y.clientCta}$`));
    await page.keyboard.press('Enter');

    // Лист согласия: фокус внутри листа, флажок достижим Tab и отмечается пробелом.
    await expect(page.getByText(A11Y.consentTitle).first()).toBeVisible();
    await expect.poll(async () => (await focused(page, A11Y.consentTitle)).inSheet, 'фокус не внутри листа «לפני שמתחילים»').toBe(true);
    const box = page.getByRole('checkbox').first();
    for (let i = 0; i < 15 && !(await box.evaluate((e) => e === document.activeElement)); i++) await page.keyboard.press('Tab');
    await expect(box).toBeFocused();
    const ring = await page.evaluate(() => {
      const e = document.activeElement as HTMLElement;
      const t = (e.closest('label') as HTMLElement) || e;
      const a = getComputedStyle(e);
      const b = getComputedStyle(t);
      const vis = (cs: CSSStyleDeclaration) => (cs.outlineStyle !== 'none' && parseFloat(cs.outlineWidth) >= 2) || cs.boxShadow !== 'none';
      return vis(a) || vis(b) || !!t.querySelector(':focus-visible');
    });
    expect(ring, 'нет видимого фокуса на флажке согласия').toBe(true);
    await page.keyboard.press('Space');
    await expect(box).toBeChecked();
    await tabTo(page, A11Y.consentCta, 10);
  });

  test(`контраст текста ≥4.5:1 (крупный ≥3:1) на ברוכים הבאים / איך זה עובד / פרטי הלקוח / לפני שמתחילים / «צריכים עזרה?» — 390 и 1440 @desktop @data ${HASH}`, async ({ browser, page, baseURL }, testInfo) => {
    test.setTimeout(4 * 60_000);
    const name = `QA-AUTO-A11Y-C-${runStamp()}`;
    const link = await newCandidateLink(browser, name, baseURL!);
    testInfo.annotations.push({ type: 'test-data', description: `кандидат «${name}» (согласие не отмечено), не удаляется` });
    await blockCallStarts(page);

    await page.goto(link);
    // Источник: AC7 / דרישה 8 «ניגודיות צבעים של 4.5:1 לפחות»; факт 14.10: минимум 6.24:1 (axe — 0 нарушений).
    for (const [i, s] of SCREENS.entries()) {
      await expect(page.getByRole('button', { name: s.ready })).toBeVisible({ timeout: 30_000 });
      for (const w of [390, 1440]) {
        await page.setViewportSize({ width: w, height: w < 768 ? 844 : 900 });
        await expectContrastOk(page, `${s.id} @${w}`);
        if (i === 0) {
          await tapBtn(page, A11Y.help);
          await expect(page.getByText(A11Y.helpTitle, { exact: true }).filter({ visible: true }).first()).toBeVisible();
          await expectContrastOk(page, `help-sheet @${w}`);
          await tapBtn(page, A11Y.helpClose);
          await expect(page.getByText(A11Y.helpTitle, { exact: true }).filter({ visible: true })).toHaveCount(0);
        }
      }
      await tapBtn(page, s.ready);
    }
    await expect(page.getByText(A11Y.consentTitle).first()).toBeVisible();
    for (const w of [390, 1440]) {
      await page.setViewportSize({ width: w, height: w < 768 ? 844 : 900 });
      await expectContrastOk(page, `consent-sheet @${w}`);
    }
  });

  test(`браузер без микрофона (navigator.mediaDevices нет) → тех. проверка: «הבדיקה לא הצליחה», «הדפדפן הזה לא מאפשר שימוש במיקרופון», «נתמכות שתי הגרסאות האחרונות…», «Chrome · Safari · Edge · Firefox», «פנייה לגורם אנושי»; без горизонтальной прокрутки @data ${HASH}`, async ({ browser, page, baseURL }, testInfo) => {
    test.setTimeout(3 * 60_000);
    const name = `QA-AUTO-A11Y-U-${runStamp()}`;
    const link = await newCandidateLink(browser, name, baseURL!);
    testInfo.annotations.push({ type: 'test-data', description: `кандидат «${name}» (согласие отмечено, тех. проверка не пройдена), не удаляется` });
    await page.addInitScript(NO_MEDIA_DEVICES);
    const blocked = await blockCallStarts(page);

    await page.goto(link);
    for (const s of SCREENS) await tapBtn(page, s.ready);
    await page.getByRole('checkbox').first().check();
    await tapBtn(page, A11Y.consentCta);

    // Источник: AC6 «הודעה ברורה כאשר הדפדפן אינו נתמך» + список поддерживаемых браузеров (דרישה 7).
    await expect(page.getByText('הדפדפן הזה לא מאפשר שימוש במיקרופון').first()).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText('הבדיקה לא הצליחה').first()).toBeVisible();
    await expect(page.getByText(/נתמכות שתי הגרסאות האחרונות של כל אחד מהם/)).toBeVisible();
    await expect(page.getByText('Chrome · Safari · Edge · Firefox')).toBeVisible();
    await expect(page.getByRole('button', { name: 'פנייה לגורם אנושי', exact: true })).toBeVisible();
    await expect(page.getByRole('button', { name: 'להתחיל בדיקה' })).toHaveCount(0);
    const { sw, vw } = await scrollWidth(page);
    expect(sw, 'горизонтальная прокрутка на экране «לא נתמך»').toBeLessThanOrEqual(vw);
    expect(blocked.start + blocked.voice, 'старт попытки').toBe(0);
  });
});
